// v26.xx (aip4), the cloud review of 2026-10-15 (finding 11): "suppression counts each round many times, and one shotgun blast pins". The first cut
// kept only the LAST round that passed a man (suppB), so two rounds in flight near him took turns and each was counted again every frame it stayed
// within 70 units (about 8 frames), and each of the six pellets of one blast was a round of its own against the four a pin needs. Now each round
// is counted ONCE for each man (b.suppL lists the men it has been counted for) and every round of one trigger pull shares a number (b.sid), so a
// blast of pellets counts once. The pin is the same: SUPP_N rounds inside SUPP_WIN seconds. No random number: a list and a number.
function suppPass(b,en){
  var L=b.suppL||(b.suppL=[]);
  if(L.indexOf(en)>=0) return false;
  L.push(en);
  if(b.sid&&en.suppSid===b.sid) return false;
  en.suppSid=b.sid||0;
  return suppHit(en);
}
